drop policy if exists "progression_metric_events_own_insert" on public.progression_metric_events; create policy "progression_metric_events_own_insert" on public.progression_metric_events for insert to authenticated with check ((select auth.uid()) = user_id and source_type <> 'system'); drop policy if exists "promotion_redemptions_own_insert" on public.promotion_redemptions; create policy "promotion_redemptions_own_insert" on public.promotion_redemptions for insert to authenticated with check ((select auth.uid()) = user_id);
